import{_ as a,C as u,o as i,c as l,j as s,a as o,E as t,a2 as r}from"./chunks/framework.BxGh02fV.js";const f=JSON.parse('{"title":"Carte","description":"","frontmatter":{"title":"Carte"},"headers":[],"relativePath":"guide/ontologie.md","filePath":"guide/ontologie.md"}'),g={name:"guide/ontologie.md"};function c(p,e,d,m,v,h){const n=u("Capture");return i(),l("div",null,[e[0]||(e[0]=s("h1",{id:"carte",tabindex:"-1"},[o("Carte "),s("a",{class:"header-anchor",href:"#carte","aria-label":'Permalink to "Carte"'},"​")],-1)),e[1]||(e[1]=s("p",null,[o("Cet écran est la carte de votre projet : ses axes de développement, rangés en couches et reliés entre eux, avec leur avancement calculé depuis le registre. Vous y venez pour voir d'un coup d'œil d'où vient le projet, où il en est et où il va, pour ranger la carte à votre façon, et pour trancher ce que l'agent propose. On l'ouvre par "),s("strong",null,"Carte"),o(", dans le groupe « Pilotage » de la barre latérale.")],-1)),t(n,{name:"ontologie",alt:"L'écran Carte : l'arbre des éléments à gauche, la carte rangée en quartiers le long du fil de conception (① But … ⑦ Capacités réalisées, Périphérie, Hors fil), le dock en bas"}),e[2]||(e[2]=r('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>L&#39;écran se lit en deux zones. <strong>En haut, le pilotage</strong> : la version courante ; la pastille <strong>N propositions de l&#39;agent</strong> quand l&#39;agent attend une réponse ; <strong>À traiter</strong> (avec le nombre de points) et <strong>Historique</strong>, qui ouvrent leur panneau à côté de la carte ; <strong>Annuler le rangement de l&#39;agent</strong> quand l&#39;agent vient de ranger la carte ; <strong>Exporter</strong>. <strong>À gauche de la carte, l&#39;arbre des éléments</strong> : toute la structure de la carte affichée, sur toute la hauteur — les zones et sous-groupes d&#39;une disposition, ou les couches et groupes de Personnalisée, chacun avec le nombre de ses éléments. <strong>Sur la carte, le visuel</strong> : en haut, centrés, <strong>Rechercher…</strong>, la lecture (<strong>Passé</strong>, <strong>Présent</strong>, <strong>Cible</strong>) et <strong>Filtres</strong> ; le <strong>dock</strong> en bas, centré — les types d&#39;atomes en icônes (faute de place, quand un panneau est ouvert, ils se replient derrière <strong>Ajouter</strong>), puis <strong>Sélection</strong>, <strong>Groupe (F)</strong>, <strong>Grille</strong>, <strong>Visite</strong> et le choix de <strong>disposition</strong> ; en bas à droite, la mini-carte et le zoom — <strong>−</strong>, le pourcentage (un clic revient à 100 %), <strong>+</strong>, <strong>Tout voir</strong> et <strong>Options d&#39;affichage</strong>. Chaque panneau de droite se ferme par sa croix.</p><p>Sur la carte :</p><ul><li>dans <strong>Personnalisée</strong>, une <strong>couche</strong> n&#39;est plus un cadre imposé : une zone de couche que vous aviez posée s&#39;affiche comme un <strong>groupe</strong> ordinaire, que vous déplacez, renommez, supprimez ou dans lequel vous rangez des sous-groupes ; un <strong>groupe</strong> est un cadre libre que vous tracez vous-même. Dans une disposition calculée, les cadres sont des <strong>zones</strong> arrondies, une par étape du fil, et la couche n&#39;y est plus qu&#39;un sous-groupe discret ;</li><li>chaque <strong>atome</strong> est un élément : l&#39;entête, marqué de l&#39;icône de son type, est coloré selon ce type (but, acteur, capacité, composant, module, interface, entité de données, flux, contrainte, décision, risque, jalon), avec sa priorité ; la <strong>nature technique</strong> d&#39;un composant (écran, service, API…) se lit dans un badge, avec son icône, à côté de son type ; en pied, sa <strong>révision</strong> (<strong>À réviser</strong>, <strong>À cadrer</strong>, <strong>Cadré</strong>, <strong>Validé</strong>) et son <strong>avancement</strong>, calculé depuis les épics, stories, tâches et évolutions de son pipe. Ce qui est fait passe en demi-teinte, ce qui est en cours reste plein. Un <strong>▲</strong> signale un point à traiter : un clic dessus l&#39;ouvre ;</li><li>chaque <strong>lien</strong> est une courbe de l&#39;atome source vers l&#39;atome cible, avec son type et sa nature. Ses extrémités se répartissent le long des bords quand plusieurs liens partent du même côté.</li></ul><p><strong>Filtres</strong> ouvre cinq listes — <strong>Couche</strong>, <strong>Horizon</strong>, <strong>Avancement</strong>, <strong>Révision</strong>, <strong>Épic</strong> — et estompe ce qui ne correspond pas, sans rien cacher : la carte garde sa forme. Chaque filtre actif devient une pastille à côté du bouton ; sa croix le retire, lui seul. Trois lectures répondent chacune à une question, écrite à côté de leurs boutons : <strong>Passé</strong> — « Qu’avons-nous livré ? » (ce qui est fait reste en couleur, avec la version qui l’a livré, « livré en v0.2.47 », ou « fait, non livré ») ; <strong>Présent</strong> — « Qu’est-ce qui avance ? » (ce qui est en cours, ce qui porte une alerte et ce qui reste <strong>À cadrer</strong>) ; <strong>Cible</strong> — « Où allons-nous ? » (une couleur par horizon, et les <strong>écarts</strong> : visé Maintenant mais pas commencé, ou visé sans aucun travail). Le reste s’efface, grisé. La légende compte chaque entrée ; un clic sur une entrée ne garde qu’elle, un second la retire.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><p>Chaque geste est enregistré aussitôt. <strong>⌘Z</strong> l&#39;annule et <strong>⇧⌘Z</strong> le rétablit, pour tous les gestes de la séance.</p><ul><li><strong>Naviguer</strong> : la molette ou le pincement zooment autour du pointeur ; maintenir <strong>Espace</strong> et glisser déplace la vue ; <strong>⌘0</strong> ou <strong>⇧1</strong> cadre tout (<strong>Tout voir</strong>), <strong>⌘1</strong> revient à 100 % ; les boutons du zoom font de même. Zoom et cadrages glissent en douceur ; tout nouveau geste les interrompt. La mini-carte, au-dessus du zoom, se clique pour recentrer la vue ; cliquer puis glisser la déplace en direct. Vue de loin, chaque zone affiche son nom en grand, en haut à gauche.</li><li><strong>Sélectionner</strong> : un clic sur un élément ouvre son panneau ; <strong>⇧</strong>-clic ou <strong>⌘</strong>-clic ajoute à la sélection (ou en retire) ; un rectangle tracé sur le fond sélectionne les éléments et les groupes qu&#39;il contient entièrement, <strong>⇧</strong> ou <strong>⌘</strong> l&#39;ajoute à la sélection en cours. Plusieurs éléments sélectionnés, atomes et groupes mêlés, se stylent d&#39;un geste : la boîte de style montre la valeur qu&#39;ils ont en commun, ou « mixte » ; <strong>Échap</strong> désélectionne ; <strong>Suppr</strong> retire la sélection, après une confirmation qui nomme ce qui part (« Supprimer 2 atomes et 3 liens ? »), comme toute suppression.</li><li><strong>Ranger</strong> : glissez un atome ou un cadre (un cadre emporte ses atomes) ; un groupe se saisit par son en-tête, son fond ou sa bordure, une zone de disposition par sa bordure. Sélectionné, un cadre montre sa poignée de taille dans le coin bas-droit. L&#39;élément reste là où vous le lâchez. Il s&#39;accroche à la grille (<strong>Grille</strong>, <strong>⌘&#39;</strong>) et aux bords et centres des autres objets ; des guides magenta l&#39;indiquent, et les <strong>écarts égaux</strong> entre voisins sont cotés. Maintenir <strong>⌥</strong> suspend l&#39;accroche. Déposer un atome dans un groupe l&#39;y range ; dans une couche, change sa couche.</li><li><strong>Choisir une disposition</strong> : le bouton de disposition, au bout du dock, propose <strong>Profils</strong>, <strong>Quartiers</strong>, <strong>Cercles</strong> et <strong>Imbrication</strong>, puis <strong>Personnalisée</strong> et vos dispositions nommées. <strong>Profils</strong> lit la carte comme vous pensez votre système, qui fait quoi puis ce qui le rend possible : les <strong>Buts</strong> en haut, puis une colonne de <strong>fonctionnalités dédiées</strong> par typologie d&#39;utilisateurs, les <strong>fonctionnalités partagées</strong> regroupées par qui les partage, <strong>Sans profil</strong> (les capacités qu&#39;aucun acteur n&#39;utilise encore) et le <strong>Socle commun</strong> ; chaque capacité forme un îlot avec ce qui la réalise, son élément en tête marqué d&#39;un bord épais. C&#39;est la disposition par défaut : la carte s&#39;y ouvre tant que Personnalisée est vierge. Quartiers, Cercles et Imbrication rangent la carte selon le fil de conception — ① But → ② Capacités → ③ Cibles → ④ Modules → ⑤ Composants → ⑥ Décisions → ⑦ Capacités réalisées, avec la <strong>Périphérie</strong> (risques, contraintes, ressources) et le <strong>Hors fil</strong> (ce qui n&#39;a aucun lien) à part : <strong>Quartiers</strong> en quartiers successifs, <strong>Cercles</strong> en spirale autour des modules, <strong>Imbrication</strong> en boîtes emboîtées (Intention, Solution, Décisions). Un fil pâle, numéroté, relie les étapes. Ces dispositions sont calculées à l&#39;affichage et n&#39;écrivent rien ; votre choix est gardé dans votre profil, il ne change pas la carte des autres.</li><li><strong>Votre travail d&#39;abord</strong> : vos groupes, leurs noms, leurs couleurs et les éléments que vous y avez mis sont <strong>communs à toutes les dispositions</strong>. Quartiers, Cercles et Imbrication rangent chacun de vos groupes d&#39;un bloc, dans l&#39;étape qui porte le plus de ses éléments ; un groupe sans élément va dans <strong>Vos groupes</strong>. Une boîte calculée que vous avez renommée ou colorée garde son nom et sa couleur d&#39;une disposition à l&#39;autre ; quand une disposition n&#39;a pas de boîte équivalente, un bandeau le dit, et rien n&#39;est perdu. Renommer ou colorer un groupe, colorer un élément, créer un groupe s&#39;appliquent partout, quelle que soit la disposition affichée.</li><li><strong>Garder une disposition</strong> : une disposition se <strong>crée</strong>, elle n&#39;écrase jamais rien. Dans une disposition calculée, <strong>Garder cette disposition</strong>, ou simplement déplacer un élément, crée une disposition à vous, « Quartiers retouchée » ; un bandeau le dit, avec <strong>Renommer</strong> et <strong>Annuler</strong>. <strong>Personnalisée</strong> est la disposition du projet, partagée avec l&#39;équipe : elle ne change que par un geste fait dans Personnalisée. Vos dispositions nommées sont à vous seul (elles ne partent pas dans le dépôt) ; le sélecteur les renomme, les duplique ou les supprime, et une suppression s&#39;annule depuis son bandeau. Un élément qu&#39;une disposition ne place pas encore y arrive près de ses voisins, marqué <strong>à placer</strong>, jusqu&#39;à ce que vous le posiez.</li></ul>',8)),t(n,{name:"ontologie-dispositions",alt:"Le sélecteur de dispositions : Quartiers, Cercles et Imbrication calculées ; Personnalisée, une disposition à soi et la proposition de l'agent, marquée « Proposée par l'agent »"}),e[3]||(e[3]=r("<ul><li><strong>La proposition de l&#39;agent</strong> : quand vous demandez à l&#39;agent de ranger la carte, il crée sa propre disposition, « Proposition de l&#39;agent — &lt;date&gt; », marquée « Proposée par l&#39;agent » dans le sélecteur. Il part de <strong>Profils</strong> et s&#39;inspire de vos couleurs et de vos groupes, mais ne touche jamais à votre travail ni à Personnalisée — sauf sur une disposition où vous avez coché <strong>Permettre la modification par l&#39;agent</strong> (décochée par défaut, Personnalisée comprise) : il y range alors directement, et <strong>Annuler le rangement de l&#39;agent</strong> défait son dernier rangement. L&#39;agent ne peut pas cocher cette case lui-même. Un bandeau dit ce qu&#39;il propose (groupes, couleurs, rattachements) ; un élément qu&#39;il range dans un de vos groupes est marqué <strong>suggestion</strong>. <strong>Garder tout</strong> fait passer la proposition dans votre travail ; <strong>Garder</strong>, dans l&#39;inspecteur, ne garde qu&#39;un élément ; ⌘Z annule. <strong>Supprimer la proposition</strong> la retire.</li></ul>",1)),t(n,{name:"ontologie-proposition-agent",alt:"Une proposition de l'agent : le bandeau dit ce qu'elle propose, avec Garder tout et Supprimer la proposition ; son groupe Facturation à venir est sélectionné, et l'inspecteur propose de le garder"}),e[4]||(e[4]=r("<ul><li><strong>Décrire un groupe</strong> : dans le panneau d&#39;un groupe, <strong>Métadonnées</strong> liste ce que le groupe porte ; le bouton <strong>+</strong> ouvre un tableau où chaque ligne choisit une métadonnée comprise par Effortless, puis sa valeur parmi ce que le projet contient : un <strong>épic</strong>, une <strong>story</strong>, une <strong>décision</strong>, une <strong>évolution</strong>, une <strong>stack</strong>, un <strong>document</strong>, un <strong>horizon</strong> ou une <strong>couche</strong>. La fiche à droite dit à quoi sert chaque métadonnée, à quoi elle se lie, ce qu&#39;en font Effortless et l&#39;agent. Rien ne s&#39;invente : une clé inconnue est refusée ; une clé ancienne non comprise est gardée et signalée. Le groupe affiche ses métadonnées au bout de son en-tête (l&#39;état de l&#39;épic cité, par exemple), et un élément créé dans le groupe en reçoit la couche, la stack, l&#39;horizon et la citation du travail dans son pipe ; le bandeau le dit.</li></ul>",1)),t(n,{name:"ontologie-metadonnees",alt:"La modale des métadonnées du groupe Pôle planning : un épic et une stack choisis dans les listes du projet, et la fiche qui explique la clé"}),e[5]||(e[5]=r("<ul><li><strong>Visiter</strong> : <strong>Visite</strong> parcourt le fil étape par étape (<strong>Précédent</strong>, <strong>Suivant</strong>, <strong>Quitter</strong>, ou <strong>Échap</strong>). L&#39;étape est cadrée et entourée d&#39;un halo, le reste s&#39;estompe ; un cartouche dit ce que l&#39;étape apporte au raisonnement et, pour chaque élément, ce qu&#39;il relie en amont (une capacité, le but qu&#39;elle sert). À l&#39;étape ⑥, chaque décision rattachée se lit dans le registre, en direct : la décision, son <strong>motif</strong>, les <strong>alternatives écartées</strong> (barrées, en fantôme) et les forces de la périphérie qui ont pesé ; ce qui n&#39;est pas consigné le dit (« motif non consigné »). La visite n&#39;écrit rien. Sur une proposition de l&#39;agent dont il a écrit le <strong>parcours</strong>, la visite suit ce parcours : une étape par moment du raisonnement, dans son ordre, avec son titre et sa phrase ; chaque étape montre ses groupes (éléments et sous-groupes compris) et les éléments qu&#39;elle nomme. Le fil pâle du canevas passe alors par ces étapes, numérotées comme le compteur de la visite.</li></ul>",1)),t(n,{name:"ontologie-visite",alt:"La visite guidée à l'étape ⑥ Décisions : la décision mise en avant sur la carte, et dans le cartouche son texte, son motif et l'alternative écartée, barrée"}),e[6]||(e[6]=r('<ul><li><strong>Ajouter</strong> : glissez une icône du dock sur la carte, ou cliquez-la pour poser l&#39;atome au centre de la vue ; il naît <strong>À cadrer</strong>. L&#39;outil <strong>Groupe (F)</strong> trace un groupe : glissez sur le fond pour dessiner un rectangle ; les éléments qu&#39;il entoure en font partie, et le déplacer les emporte. Lâché au-dessus d&#39;un groupe, le nouveau groupe en devient un sous-groupe. Quand un groupe est sélectionné, tout élément ajouté depuis le dock y entre, à une place libre, et le groupe reste sélectionné pour le suivant. Un groupe ne touche que la présentation de la carte, ni le schéma ni les versions.</li><li><strong>Créer en liant</strong> : tirez une poignée et lâchez dans le vide ; une petite fenêtre propose les éléments compatibles avec celui dont vous partez (depuis un composant : <strong>réalise → capacité</strong>, <strong>expose → interface</strong>, <strong>persiste → entité</strong>…). Choisissez, nommez, <strong>Créer</strong> : l&#39;élément naît à cet endroit, déjà relié. <strong>⌘Z</strong> retire les deux.</li><li><strong>Lier</strong> : survolez un atome, tirez une de ses quatre poignées vers un autre atome ; pendant le geste, les atomes qui peuvent recevoir le lien s&#39;éclairent, les autres s&#39;estompent. La fenêtre <strong>Nouveau lien</strong> ne propose que les types permis par les règles pour ce couple, sans ceux qui relient déjà les deux atomes ; choisissez la nature, une description, puis <strong>Créer le lien</strong> ; un clic en dehors la ferme.</li><li><strong>Tracer un lien</strong> : sélectionnez-le pour voir ses points de passage ; glissez-les, double-cliquez sur un segment pour en ajouter un, sur un point pour l&#39;enlever ; ses extrémités se re-glissent vers un autre côté. Son <strong>étiquette</strong> se glisse le long du lien, et un peu à côté ; <strong>Recentrer l&#39;étiquette</strong>, au clic droit, la remet à sa place automatique.</li><li><strong>Parcourir l&#39;arbre</strong> : l&#39;arbre défile en lui-même ; ses chevrons déplient un cadre. Choisir un élément le sélectionne, le centre et s&#39;en rapproche un peu ; choisir un cadre le cadre. L&#39;élément sélectionné sur la toile est surligné dans l&#39;arbre. Après un clic dans l&#39;arbre, au clavier, <strong>↑</strong> et <strong>↓</strong> passent d&#39;une ligne à l&#39;autre et montrent l&#39;élément atteint sur la toile (un groupe atteint se déplie) ; <strong>→</strong> déplie un cadre ou entre dedans, <strong>←</strong> le replie ou remonte au cadre parent ; <strong>Début</strong> et <strong>Fin</strong> vont à la première et à la dernière ligne. Glissez un élément ou un groupe de l&#39;arbre sur un groupe pour l&#39;y rattacher : il y prend une place libre, et le groupe s&#39;agrandit s&#39;il le faut. Le bouton de son en-tête le replie en une fine poignée, et son bord droit se glisse pour l&#39;élargir (200 à 480 px) ; largeur et repli sont retrouvés à la réouverture.</li><li><strong>Chercher</strong> : <strong>⌘F</strong> place le curseur dans <strong>Rechercher…</strong> ; ce que vous tapez filtre aussi l&#39;arbre, qui ne garde que les éléments trouvés et leurs cadres, dépliés ; tapez un nom (sans souci des accents), un identifiant ou une référence du registre. Choisir un résultat sélectionne l&#39;atome, le centre et le rapproche s&#39;il était trop petit pour être lu.</li><li><strong>Trier</strong> : <strong>Filtres</strong> retient une couche, un horizon, un avancement, une révision ou un épic ; <strong>Alertes</strong> › <strong>Avec alerte</strong> ne garde que les atomes qui ont un point à traiter. Chaque cadre porte le nombre de ses alertes (▲).</li><li><strong>Se concentrer, replier</strong> : au clic droit d&#39;un cadre, <strong>Se concentrer sur ce cadre</strong> estompe le reste (la pastille <strong>Concentré</strong> ou <strong>Échap</strong> en sortent) ; le chevron au début du titre, ou <strong>Replier</strong>, réduit le cadre à une barre (« 4 atomes repliés ») où arrivent ses liens ; <strong>Déplier</strong> le rouvre. Un groupe replié devient un bloc à ports comptés, ouvrable par double-clic (voir « Groupes et sous-graphes »).</li><li><strong>Réviser</strong> : un élément proposé par l&#39;agent arrive <strong>À réviser</strong> ; un élément que vous posez vous-même naît <strong>À cadrer</strong>. <strong>Réviser</strong> (bouton du panneau, touche <strong>V</strong>, clic droit) le fait passer d&#39;<strong>À réviser</strong> à <strong>À cadrer</strong>. En lot : <strong>Réviser (n)</strong> dans le panneau d&#39;une sélection, <strong>Réviser la sélection</strong> au clic droit, ou <strong>Réviser N éléments à réviser</strong> sur un cadre ; une confirmation dit combien d&#39;éléments passent <strong>À cadrer</strong>. Un seul <strong>⌘Z</strong> annule le lot. Un élément devient <strong>Cadré</strong> quand du travail (épic, story, tâche) lui est rattaché, et <strong>Validé</strong> de lui-même quand ce travail est terminé. Seuls une décision ou un acteur, qui ne portent jamais de travail, se valident à la main : <strong>Valider</strong> les fait passer d&#39;<strong>À cadrer</strong> à <strong>Validé</strong>, <strong>Repasser à cadrer</strong> les y ramène, et il est aussi offert pour tout élément validé à la main auparavant.</li><li><strong>Réarranger un cadre</strong> : après un redimensionnement, la carte propose quelques secondes <strong>Réarranger les éléments</strong> ; le même choix est au clic droit du cadre. Les éléments se rangent dans la nouvelle largeur, dans leur ordre de lecture, les éléments reliés côte à côte, et le cadre s&#39;agrandit s&#39;il le faut.</li><li><strong>Le travail derrière un atome</strong> : un atome dit « 2 ouverts » quand des épics, stories ou évolutions de son pipe sont en cours ; le panneau les liste sous <strong>Travail au registre</strong>, chacun avec son titre et son état, et <strong>Ouvrir … au Backlog</strong> mène à sa page.</li><li><strong>Ce qui se passe</strong> : chaque action le dit dans un bandeau, en bas — pendant (« Révision de 3 éléments… »), puis le résultat (« 3 éléments révisés : … ») avec <strong>Annuler</strong> et <strong>Pourquoi ?</strong>, qui explique ce que l’action a changé ; un échec dit ce qu’il faut faire à la place. <strong>Journal</strong>, dans l’entête, garde toutes les actions de la séance.</li><li><strong>Modifier</strong> : le panneau ne montre que les propriétés du type de l’élément. Un but, un acteur ou une contrainte n’ont ni pipe, ni nature du travail, ni spécification ; une contrainte a sa <strong>source</strong>, une décision sa <strong>décision du registre</strong> et sa <strong>date</strong>, une solution, un composant ou un module son <strong>Livrable du registre</strong> (proposé seulement quand le projet a un pilotage ; l&#39;élément montre alors une pastille colorée avec le taux, voir <a href="/Effortless/guide/objectifs.html">Objectifs et jalons</a>), un jalon sa <strong>date</strong> ; les solutions (capacité, composant, module, interface, entité, flux) ont tout — spécification, documents, nature du travail (analyse, conception, code, test, rédaction, recherche, diffusion, exploitation, juridique), pipe, horizon (<strong>Fait</strong> · <strong>Maintenant</strong> · <strong>Ensuite</strong> · <strong>Plus tard</strong>), priorité. Une propriété remplie que le type n’affiche pas est signalée ; <strong>Les retirer</strong> la vide, et <strong>⌘Z</strong> la remet. Rien ne se tape quand cela existe : un document se choisit parmi ceux du projet (ou par <strong>Parcourir…</strong>, dans le dossier du projet seulement) ; un travail se rattache par <strong>Rattacher un travail du registre</strong> (épics, stories, tâches, évolutions, avec leur état) ; une décision se choisit parmi celles du registre. Un document cité qui n’existe plus est signalé en rouge. <strong>Réviser</strong>, <strong>Valider</strong> ou <strong>Repasser à cadrer</strong> apparaît selon l&#39;état de l&#39;élément (voir <strong>Réviser</strong>) ; un élément à cadrer qui porte du travail n&#39;a pas de bouton : son <strong>Validé</strong> viendra du travail terminé.</li><li><strong>Clic droit</strong> : le menu nomme l&#39;élément visé et range ses actions par intention. Sur un atome : <strong>Consulter</strong> (<strong>Ouvrir le panneau</strong>), <strong>Statut</strong> (<strong>Réviser</strong>, <strong>Valider</strong> ou <strong>Repasser à cadrer</strong> selon l&#39;état, <strong>Horizon ▸</strong>), <strong>Disposition</strong> (<strong>Revenir à la palette</strong>), <strong>Édition</strong> (<strong>Copier</strong>, <strong>Dupliquer</strong>), <strong>Cartes</strong> (<strong>Détailler dans une sous-carte</strong>, <strong>Accrocher une sous-carte</strong>, <strong>Retirer de cette carte</strong>), puis <strong>Supprimer l’élément</strong>, en rouge. Sur un lien : <strong>Nature ▸</strong>, <strong>Tracé</strong> (<strong>Redresser le lien</strong>, <strong>Recentrer l&#39;étiquette</strong>), <strong>Retirer le lien</strong>. Sur le fond : <strong>Ajouter ici</strong>, une grille d&#39;icônes, <strong>Ajouter ▸</strong> rangé en <strong>Intention</strong>, <strong>Solution</strong> et <strong>Cadre</strong>, <strong>Nouveau groupe ici</strong>, <strong>Coller ici</strong> (quand des éléments sont copiés), <strong>Nouvelle carte ici</strong>, <strong>Poser ici un élément existant</strong>, <strong>Tout voir</strong>. Sur un groupe : <strong>Copier</strong>, <strong>Dupliquer</strong> et <strong>Coller ici</strong> dans sa section <strong>Édition</strong>. Les sous-menus s&#39;ouvrent au survol ou au clic ; les flèches, <strong>Entrée</strong> et <strong>Échap</strong> s&#39;y emploient.</li><li><strong>Raccourcis</strong> : ceux qu&#39;affiche le menu agissent sans lui. Sur l&#39;atome sélectionné : <strong>V</strong> fait le pas de révision affiché (réviser, valider une décision ou un acteur, repasser à cadrer), <strong>1</strong> à <strong>4</strong> fixent l&#39;horizon, <strong>Entrée</strong> ouvre le panneau, <strong>⇧P</strong> revient à la palette, <strong>Suppr</strong> retire. Sur la carte : <strong>G</strong> crée un groupe au centre de la vue, <strong>⇧1</strong> cadre tout. Ils se taisent quand vous écrivez dans un champ.</li><li><strong>Styler</strong> : couleurs d&#39;<strong>Entête</strong>, de <strong>Fond</strong>, de <strong>Bordure</strong> et de <strong>Texte</strong> pour les atomes et les cadres, et la forme de leur bordure : <strong>Trait de bordure</strong> (<strong>Continu</strong>, <strong>Tirets</strong>, <strong>Pointillés</strong>, <strong>Double</strong>) et <strong>Épaisseur</strong> (<strong>Auto</strong>, de 0,5 à 6) ; <strong>Couleur du trait</strong>, <strong>Trait</strong> et <strong>Épaisseur</strong> pour les liens. Un clic sur une pastille ouvre la palette : pastilles proposées, <strong>nuancier</strong>, saisie hexadécimale, et <strong>Demi-teinte</strong>, qui adoucit la couleur choisie (par exemple un fond de la couleur de l&#39;entête, en plus doux). <strong>Revenir à la palette</strong> efface la couleur propre à l&#39;élément.</li><li><strong>Copier, coller, dupliquer</strong> : <strong>⌘C</strong> copie les éléments sélectionnés (Ctrl+C sous Windows), <strong>⌘V</strong> les colle un peu plus loin, <strong>⌘D</strong> les duplique ; au clic droit, <strong>Copier</strong>, <strong>Dupliquer</strong>, et <strong>Coller ici</strong> pose les copies au point visé, dans le groupe qui s&#39;y trouve. Un <strong>groupe</strong> se copie avec ses sous-groupes et ses éléments ; dupliqué, il se pose juste à droite de l&#39;original. Une copie garde le type, la description et les champs de l&#39;élément, mais ni ses références au backlog ni sa révision : elle repart <strong>À cadrer</strong>. Les liens entre éléments copiés ensemble sont recréés ; un lien vers un élément qui n&#39;est pas copié ne l&#39;est pas. Un seul <strong>⌘Z</strong> retire le collage. Dans un champ de texte, ces touches gardent leur sens habituel.</li><li><strong>Corriger l&#39;orthographe</strong> : dans un champ de texte (titre, description…), un mot mal orthographié est souligné selon les réglages de votre système ; le clic droit ouvre le menu du système, avec ses suggestions, <strong>Couper</strong>, <strong>Copier</strong> et <strong>Coller</strong>.</li><li><strong>Options</strong> : <strong>Options d&#39;affichage</strong>, près du zoom, ouvre le panneau qui règle la carte entière, pour tous. <strong>Lecture</strong> : taille des <strong>Titres</strong> et des <strong>Textes</strong> (S, M, L), <strong>Contraste</strong> normal ou élevé. <strong>Liaisons</strong> : <strong>Courbure</strong> des liens, et <strong>Liens sous les blocs</strong> visibles (on les devine à travers les éléments estompés) ou masqués. <strong>Couleurs</strong> : <strong>Palette</strong> choisit l&#39;habillage de toute la carte — <strong>Défaut</strong>, <strong>Sobre</strong>, <strong>Contraste élevé</strong>, <strong>Pastel</strong>, ou l&#39;une de <strong>Mes palettes</strong> (créées dans Préférences › Apparence), qui est alors copiée dans le projet pour que l&#39;équipe et l&#39;agent la voient ; si vous la modifiez ensuite, <strong>Mettre à jour depuis mes palettes</strong> reprend la nouvelle version. La carte suit le thème clair ou sombre de l&#39;application. Une couleur posée à la main sur un élément prime sur la palette. Chaque réglage s&#39;annule par <strong>⌘Z</strong>, et les exports SVG, PNG et PDF le reprennent.</li></ul><h3 id="ce-que-l-agent-propose" tabindex="-1">Ce que l&#39;agent propose <a class="header-anchor" href="#ce-que-l-agent-propose" aria-label="Permalink to &quot;Ce que l&#39;agent propose&quot;">​</a></h3><p>Quand l&#39;agent propose un changement, la pastille <strong>N propositions de l&#39;agent</strong> apparaît en haut. Un clic passe la carte en <strong>aperçu</strong> : un liseré laiton l&#39;entoure, et une barre flottante dit la proposition — son résumé, puis ce que le lot ferait, en clair (« ajouter 2 couches, 1 atome ; modifier 1 atome »). Sur la carte, rien n&#39;est écrit : ce qui serait ajouté apparaît en pointillés vert, marqué <strong>ajouté</strong> ; ce qui serait modifié est cerclé, marqué <strong>modifié</strong> ; ce qui serait retiré est barré. <strong>Détail</strong> liste chaque changement en une phrase ; les flèches passent d&#39;une proposition à l&#39;autre. <strong>Accepter</strong> fait passer l&#39;ontologie à la version suivante ; <strong>Refuser…</strong> demande un motif ; <strong>Quitter l&#39;aperçu</strong> rend la carte d&#39;aujourd&#39;hui.</p><p>Une proposition qui <strong>détruit</strong> quelque chose — fusionner deux atomes, retirer un atome, un lien ou une couche, sortir un élément d&#39;un de vos groupes — le dit avant tout : un encadré rouge <strong>Ce qui disparaît</strong> liste chaque perte (l&#39;atome, ses liens, ses citations du registre, le groupe qu&#39;il quitte). Une telle proposition n&#39;est jamais acceptée d&#39;office, même en mode <code>full</code> : <strong>Accepter</strong> demande une confirmation, puis <strong>Accepter quand même</strong>.</p>',4)),t(n,{name:"ontologie-effets",alt:"L'aperçu d'une fusion : l'encadré Ce qui disparaît, et la confirmation demandée avant d'accepter"}),e[7]||(e[7]=r('<h3 id="concevoir-l-architecture" tabindex="-1">Concevoir l&#39;architecture <a class="header-anchor" href="#concevoir-l-architecture" aria-label="Permalink to &quot;Concevoir l&#39;architecture&quot;">​</a></h3><p>Un <strong>composant</strong> porte une <strong>nature technique</strong> — interface utilisateur (écran, fenêtre, popup, formulaire, widget), exécution (service, tâche planifiée, CLI), échanges (API, intégration externe) ou socle (bibliothèque, base de données). Un <strong>module</strong> représente une stack du projet : dans son panneau, <strong>Stack</strong> la choisit dans la liste, ou <strong>Déclarer une stack…</strong> la crée ; l&#39;activité récente de la stack s&#39;y affiche, et un module sans travail rattaché suit l&#39;avancement des composants qu&#39;il contient. Les liens de conception : un composant <strong>réalise</strong> une capacité, un module <strong>contient</strong> des composants (un écran peut contenir des formulaires), un composant <strong>expose</strong> ou <strong>appelle</strong> une interface, <strong>persiste</strong> une entité de données, et une entité en <strong>référence</strong> une autre.</p><h3 id="a-traiter" tabindex="-1">À traiter <a class="header-anchor" href="#a-traiter" aria-label="Permalink to &quot;À traiter&quot;">​</a></h3><p><strong>À traiter</strong> dit chaque point en une phrase, avec le bouton qui le règle : <strong>Passer l&#39;horizon à « Maintenant »</strong> quand l&#39;horizon contredit l&#39;avancement, <strong>Retirer la référence</strong> quand le pipe cite un épic qui n&#39;existe plus, <strong>Rattacher</strong> quand un épic ouvert n&#39;est rattaché à aucun atome (choisissez l&#39;atome, l&#39;épic entre dans son pipe), <strong>Relier à une stack</strong> pour un module qui n&#39;en a pas, <strong>Créer le composant</strong> pour une capacité que rien ne réalise, <strong>Renseigner son pipe</strong> ou <strong>Ouvrir</strong> pour le reste. <strong>Situer</strong> amène l&#39;atome au centre de la carte. Chaque bouton est un geste comme les autres : <strong>⌘Z</strong> l&#39;annule.</p><p>Sur une sous-carte, la liste ne garde que les points des éléments <strong>posés sur cette carte</strong> — un voisin repris dans <strong>Contexte</strong> n&#39;en fait pas partie. <strong>Toute la conception</strong> montre tous les points ; ouvrir une autre carte rétablit le filtre. Les alertes elles-mêmes se calculent toujours sur toute la conception.</p><h3 id="feuille-de-route" tabindex="-1">Feuille de route <a class="header-anchor" href="#feuille-de-route" aria-label="Permalink to &quot;Feuille de route&quot;">​</a></h3><p>La bascule <strong>Carte</strong> · <strong>Feuille de route</strong>, dans l&#39;entête, range les capacités, composants, modules, jalons et buts en <strong>couloirs</strong> : une ligne par couche de la Carte, une colonne par horizon — <strong>Maintenant</strong>, <strong>Ensuite</strong>, <strong>Plus tard</strong>, <strong>Sans horizon</strong> ; <strong>Fait (N)</strong>, repliée à gauche, réunit ce dont l&#39;avancement est fait. On lit « quand » en suivant la ligne, et « dans quel ordre » en descendant une case. Sur une sous-carte, la feuille de route ne montre que les éléments posés sur cette carte ; <strong>Toute la conception</strong> les montre tous. Un élément priorisé ici prend son rang parmi toute la colonne, éléments cachés compris. Chaque élément a le dessin de la Carte (entête, icône, avancement, travaux ouverts) ; les dépendances sont tracées entre les éléments, en rouge quand elles sont en retard.</p><ul><li><strong>Prioriser</strong> : glissez un élément d&#39;une colonne à l&#39;autre de son couloir pour changer son horizon, ou dans sa case pour changer son rang ; au clavier, <strong>⌥</strong> + flèches. Glisser vers un autre couloir est refusé : la couche se change dans le panneau. Chaque déplacement s&#39;annule par <strong>⌘Z</strong>.</li><li><strong>Demander un arbitrage</strong> dépose la demande : l&#39;agent la voit à sa prochaine lecture de la Carte (et la phrase à lui dire est copiée). Il lit la feuille de route, ses dépendances et le travail ouvert, et propose des mouvements ; il le fait aussi de lui-même quand un couloir n&#39;a plus rien en « maintenant ». La proposition s&#39;ouvre en aperçu sur la feuille de route — chaque élément à sa nouvelle place, avec « venait de … ». Dans <strong>Détail</strong>, un mouvement qui ne vous convient pas se retire (×) ; puis <strong>Accepter</strong> ou <strong>Refuser…</strong>.</li><li><strong>Mise à jour à la fermeture</strong> : quand un épic, une story ou une tâche se ferme (ou qu&#39;une évolution est résolue), ce qui devient fait passe de lui-même à l&#39;horizon <strong>Fait</strong> ; le changement est versé à l&#39;<strong>Historique</strong> (auteur « registre ») et annoncé dans le bandeau.</li><li><strong>Dépendances</strong> : un élément posé plus tôt qu&#39;un élément dont il dépend le signale (« Dépend de …, prévu plus tard ») ; <strong>Avancer aussi cette dépendance</strong> la ramène dans la même colonne, en un seul geste.</li><li><strong>Créer l&#39;épic</strong> : nommez-le, <strong>Créer</strong> ; l&#39;épic naît au registre, déjà rattaché à l&#39;atome.</li><li><strong>Appliquer au registre</strong> donne aux évolutions ouvertes de chaque élément la priorité de sa colonne (Maintenant 1, Ensuite 2, Plus tard 3), après une confirmation qui liste les changements.</li></ul><h3 id="groupes-et-sous-graphes" tabindex="-1">Groupes et sous-graphes <a class="header-anchor" href="#groupes-et-sous-graphes" aria-label="Permalink to &quot;Groupes et sous-graphes&quot;">​</a></h3><p>Un <strong>groupe</strong> se replie en bloc, et s&#39;ouvre comme un sous-graphe : sur une grande carte, vous voyez le projet à un niveau, puis entrez dans un groupe pour n&#39;en voir que le contenu. Un groupe que vous créez (<strong>Nouveau groupe ici</strong>, touche <strong>G</strong>, ou dessiné à l&#39;outil cadre) ouvre son panneau, le curseur dans son <strong>Titre</strong> : tapez son nom.</p><ul><li><strong>Groupe replié</strong> : le groupe devient un <strong>bloc</strong> avec son titre, son nombre d&#39;éléments et un chevron. À ses bords, un <strong>port</strong> par voisin et par sens, avec le nombre de liens (« 7 → Boucle ») ; le survol détaille les types de liens (« utilise ×3, réalise ×4 »). Les liens entre deux blocs repliés se regroupent en un seul trait compté.</li><li><strong>Replier et déplier</strong> : le chevron du groupe, ou <strong>Replier</strong> et <strong>Déplier</strong> au clic droit. Au Dock, <strong>Tout replier</strong> et <strong>Tout déplier</strong> agissent sur tous les groupes d&#39;un coup ; chacun s&#39;annule par <strong>⌘Z</strong>. Sur la Carte entière, <strong>Tout replier</strong> donne la vue d&#39;ensemble : un bloc par groupe de premier niveau. Un groupe qui n&#39;en enveloppe qu&#39;un seul autre est traversé : on replie le premier niveau qui compte plusieurs groupes.</li><li><strong>Entrer dans un groupe</strong> : double-cliquez sur son en-tête, ou sur son bloc replié. La Carte ne montre plus que son contenu, sous-groupes compris, à sa place et avec ses positions actuelles. Les liens vers l&#39;extérieur deviennent des <strong>portes</strong> au bord : un clic sur une porte entre dans le groupe voisin, ou revient à la Carte entière si ce voisin est hors groupe (« Hors groupe »).</li><li><strong>Revenir</strong> : le <strong>fil d&#39;Ariane</strong>, en haut à gauche, indique où vous êtes (<code>Cartes › Carte principale › Groupe › Sous-groupe</code>) ; un clic sur un niveau l&#39;y ramène, et <strong>Échap</strong> remonte d&#39;un cran.</li><li><strong>Rechercher</strong> : choisir un élément situé dans un groupe replié ouvre ce groupe et sélectionne l&#39;élément.</li></ul><p>Entrer dans un groupe ne modifie rien : c&#39;est un écran, pas une écriture. Les gestes faits à l&#39;intérieur (déplacer, styler) s&#39;écrivent dans la disposition, comme partout. Chaque disposition retient le niveau où vous l&#39;aviez laissée. Sans aucun groupe, le Dock ne montre pas ces commandes, et la Carte reste celle que vous connaissez.</p><h3 id="rangement-automatique" tabindex="-1">Rangement automatique <a class="header-anchor" href="#rangement-automatique" aria-label="Permalink to &quot;Rangement automatique&quot;">​</a></h3><p>La Carte peut ranger elle-même les éléments d&#39;un groupe : vous gardez la main sur l&#39;ordre et le contenu, elle s&#39;occupe des positions. Les exemples suivent le projet fictif d&#39;atelier (Devis, Facture émise, Relance).</p><ul><li><strong>Trois niveaux</strong>, dans le panneau <strong>Options</strong> : <strong>Manuel</strong> (rien n&#39;est rangé), <strong>Semi-auto</strong> (réglage par défaut : les éléments existants ne bougent pas, ceux que vous créez ensuite sont rangés) et <strong>Auto</strong> (tous les éléments sont rangés, ceux du fond de la carte compris : plus de poignées de redimensionnement, liens au tracé automatique, hauteur qui suit le titre). Le niveau, les espacements et le pas de la grille valent pour toute la Carte : réglés sur la carte principale, ils s&#39;appliquent aux sous-cartes, et vous pouvez les régler depuis n&#39;importe quelle carte.</li><li><strong>Par élément</strong> : l&#39;option <strong>Rangement automatique</strong> du panneau de style choisit si un bloc est rangé. En Auto elle est grisée (« imposé par le réglage global »). <strong>Poser ici un élément existant</strong> ne range pas l&#39;élément posé.</li><li><strong>Lignes ou grille</strong> : un groupe rangé se présente en <strong>Grille</strong> (par défaut) ou en <strong>Lignes</strong>. En grille, le nombre de <strong>colonnes</strong> est <strong>Auto</strong> (selon la largeur du groupe) ou fixé à N ; en lignes, l&#39;<strong>alignement horizontal</strong> place chaque ligne. L&#39;<strong>alignement vertical</strong> vaut dans les deux modes. En grille, les éléments remplissent leur colonne : l&#39;alignement horizontal est alors grisé.</li><li><strong>Espacements</strong> : marges intérieures du groupe (gauche, haut, droite, bas), marge autour de chaque élément et écart entre éléments (horizontal, vertical). Un groupe peut surcharger ces valeurs pour lui seul.</li><li><strong>Tailles</strong> : la hauteur d&#39;un élément rangé suit son titre (jamais sous la hauteur standard) ; la hauteur que vous lui aviez choisie est gardée et revient quand il n&#39;est plus rangé (en Semi-auto par exemple) ; un groupe rangé épouse son contenu en hauteur ; sa poignée de largeur change le nombre de colonnes. Un élément rangé n&#39;a pas de poignées de redimensionnement.</li><li><strong>Glisser</strong> : en faisant glisser « Relance » dans un groupe rangé, ses voisins s&#39;écartent d&#39;une place pour montrer où elle ira ; au lâcher, elle prend cette place en un seul geste, annulable par <strong>⌘Z</strong>. <strong>⌥ + flèches</strong> déplace l&#39;élément sélectionné d&#39;une place. Un élément qui quitte le groupe vers le fond de la carte s&#39;aligne sur la grille.</li><li><strong>Liens</strong> : les liens d&#39;un élément rangé suivent le tracé automatique ; leurs points de passage manuels sont conservés et reviennent si le rangement est coupé.</li><li><strong>Couper le rangement d&#39;un groupe</strong> fige ses éléments là où ils sont (annulable). Les dispositions calculées (Profils, Quartiers, Cercles, Imbrication) ne sont pas rangées par ce réglage.</li><li><strong>Animations</strong> : les déplacements durent environ 0,2 s ; ils sont coupés quand <strong>Réduire les animations</strong> est actif dans macOS.</li></ul><h3 id="plusieurs-cartes" tabindex="-1">Plusieurs cartes <a class="header-anchor" href="#plusieurs-cartes" aria-label="Permalink to &quot;Plusieurs cartes&quot;">​</a></h3><p>Une carte unique finit par être trop grande pour se lire. Vous pouvez <strong>découper la conception par lot</strong> : la <strong>carte principale</strong> donne les grandes lignes, et des <strong>sous-cartes</strong> détaillent chacune un périmètre. Il n&#39;y a toujours qu&#39;une conception : un élément peut figurer sur plusieurs cartes sans être dupliqué. On ne voit qu&#39;une carte à la fois, et l&#39;on passe de l&#39;une à l&#39;autre en naviguant. Les exemples ci-dessous suivent un projet fictif de gestion d&#39;atelier, avec une sous-carte « Facturation ».</p><ul><li><strong>Créer une carte</strong> : au clic droit, <strong>Nouvelle carte ici</strong> sur le fond, <strong>Nouvelle sous-carte dans ce groupe</strong> sur un groupe, <strong>Accrocher une sous-carte</strong> sur un élément ; ou, dans l&#39;arbre des cartes, <strong>Nouvelle sous-carte…</strong> au menu d&#39;une carte. Un nom et un objectif sont demandés (« Facturation » — « Émettre les factures et suivre les relances »). Ce que vous avez cliqué devient l&#39;<strong>accroche</strong> de la sous-carte : un élément, un groupe, ou la carte elle-même.</li><li><strong>Détailler dans une sous-carte</strong> : sélectionnez des éléments, ou un groupe, puis <strong>Détailler dans une sous-carte</strong> (ou <strong>Détailler ce groupe dans une sous-carte</strong>) au clic droit. La sous-carte naît avec ces éléments, à leur position — un groupe y garde sa mise en page. Sur la carte parente, ils sont retirés et un <strong>élément-carte</strong> prend leur place. Un seul <strong>⌘Z</strong> défait le tout.</li><li><strong>L&#39;élément-carte</strong> dit d&#39;un coup d&#39;œil le nom et l&#39;<strong>objectif</strong> de la sous-carte, et ce qu&#39;elle apporte : le nombre d&#39;éléments par type, sous-cartes comprises, et la part déjà faite. Ses liens vers le reste se regroupent et se comptent, comme ceux d&#39;un groupe replié (« 3 → Client »). Un double-clic ouvre la sous-carte. Une sous-carte accrochée à un élément y laisse une marque <strong>⤵</strong> : son survol nomme la sous-carte, un double-clic l&#39;ouvre.</li><li><strong>Naviguer</strong> : le fil d&#39;Ariane commence par <strong>Cartes</strong>, puis enchaîne les cartes et les groupes (<code>Cartes › Carte principale › Facturation › Relances</code>). Un clic sur <strong>Cartes</strong> montre, dans le panneau de gauche, l&#39;<strong>arbre des cartes</strong> : la principale, et chaque sous-carte rangée sous sa carte, son groupe ou son élément d&#39;accroche. Un clic sur une carte l&#39;ouvre, et le panneau revient aux éléments de la carte. Le menu d&#39;une ligne renomme la carte, change son objectif, la déplace (une nouvelle accroche), la supprime, ou en fait la <strong>carte de l&#39;agent</strong>.</li><li><strong>Remonter, Sœurs</strong> : dans une sous-carte, un bandeau sous le fil d&#39;Ariane propose <strong>Remonter</strong> vers la carte parente et, quand la sous-carte partage un groupe avec d&#39;autres, ses <strong>Sœurs</strong>, qui s&#39;ouvrent d&#39;un clic.</li><li><strong>Contexte</strong> : les éléments d&#39;autres cartes liés à la sous-carte sont repris dans <strong>un seul</strong> élément <strong>Contexte</strong>, qui les nomme avec leur carte. Un clic sur un nom ouvre sa carte, l&#39;élément sélectionné. Sa largeur se règle à la poignée de son coin bas-droit : un nom trop long passe à la ligne et la hauteur suit. Élément-carte, Remonter, Sœurs et Contexte servent à naviguer : ils ne comptent ni dans les alertes, ni dans la feuille de route.</li><li><strong>Poser, retirer</strong> : <strong>Poser ici un élément existant</strong>, au clic droit du fond, cherche dans toute la conception et ajoute l&#39;élément à la carte affichée. <strong>Retirer de cette carte</strong> l&#39;en ôte sans le supprimer. Un élément qui n&#39;est plus sur aucune carte apparaît dans la branche <strong>Hors carte</strong>, en bas de l&#39;arbre : <strong>Poser sur la carte…</strong> le remet sur la carte affichée. Rien ne se perd.</li><li><strong>Supprimer une carte</strong> : la confirmation dit ce qui revient sur la carte parente — ses éléments qui n&#39;étaient sur aucune autre carte — et où se raccrochent ses sous-cartes. Les éléments ne sont pas supprimés. Si l&#39;élément ou le groupe d&#39;accroche d&#39;une sous-carte disparaît, elle se range sous sa carte parente, marquée <strong>raccrochée</strong>.</li><li><strong>Groupes, dispositions</strong> : chaque carte a ses groupes, ses positions et ses dispositions ; un élément présent sur deux cartes a une place sur chacune. Palette et options d&#39;affichage d&#39;une sous-carte suivent la principale tant que vous ne les réglez pas sur elle.</li><li><strong>La carte de l&#39;agent</strong> : l&#39;agent connaît toute la conception, mais travaille d&#39;abord sur la carte que vous lui désignez, sinon sur la <strong>carte de l&#39;agent</strong>, marquée <strong>agent</strong> dans l&#39;arbre (la principale tant que vous n&#39;en choisissez pas d&#39;autre). Ce qu&#39;il ajoute ou propose atterrit sur cette carte, et il le dit. Il peut aussi proposer une nouvelle carte, pour isoler un concept ; vous l&#39;acceptez ou la refusez comme toute proposition.</li><li><strong>Exporter plusieurs cartes</strong> : <strong>Exporter</strong> › <strong>Plusieurs cartes…</strong> ouvre l&#39;arbre des cartes à cocher (<strong>Tout cocher</strong>, <strong>Tout décocher</strong>). En SVG et en PNG, un fichier par carte cochée, dans le dossier que vous choisissez ; en PDF, un seul fichier, une carte par page ; en Mermaid et en OWL, les éléments de chaque carte, avec leurs liens vers les autres cartes notés en référence. Chaque nom de fichier porte le nom de sa carte. <strong>Carte en cours</strong> exporte, comme avant, la carte affichée.</li></ul><p>Un projet sans sous-carte ne change pas : sa carte principale contient tout, et rien n&#39;est réécrit tant que vous ne créez pas de sous-carte.</p><h3 id="historique" tabindex="-1">Historique <a class="header-anchor" href="#historique" aria-label="Permalink to &quot;Historique&quot;">​</a></h3><p><strong>Historique</strong> liste les versions, la plus récente d&#39;abord, chacune avec son résumé, son auteur, sa date et son nombre de changements. Un clic sur une version la montre sur la carte : ce qu&#39;elle a changé et qui existe encore est cerclé, ce qui a disparu depuis apparaît en pointillés. <strong>Fermer l&#39;aperçu</strong> rend la carte d&#39;aujourd&#39;hui.</p><p><strong>Exporter</strong> écrit la carte en cours en <strong>SVG</strong>, <strong>PNG</strong>, <strong>PDF</strong> (vectoriel, sur une page A4 ou A3 paysage, avec titre, version et date), <strong>Mermaid</strong> ou <strong>OWL / RDF (Turtle)</strong> ; pour plusieurs cartes, voir « Plusieurs cartes ».</p><p>Un projet sans ontologie propose <strong>Commencer vide</strong>, ou <strong>Construire depuis le projet</strong> : la carte se construit alors par l&#39;agent, à qui l&#39;écran donne la phrase à dire.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>L&#39;agent lit et propose par les verbes <code>effortless_ontology_*</code> ; il ne modifie jamais le schéma directement, il propose, et il peut ranger la carte — son dernier rangement s&#39;annule ici. C&#39;est aussi lui qui rattache les décisions du registre à l&#39;étape ⑥ : il en retient une poignée de structurantes et vous les propose en un lot, que vous acceptez ou refusez. Voir <a href="/Effortless/agent/ontologie.html">Tenir l&#39;ontologie</a>.</p>',25))])}const b=a(g,[["render",c]]);export{f as __pageData,b as default};
